import {waterHeight,createBoatWake,updateBoatWake} from './water-surface.js';
import {diverResponder} from './diver-model.js';
import {installRotaryBeacons,updateRotaryBeacons} from './rotary-beacons.js';
import * as T from 'three';
import {installRollingWheels} from './wheel-motion.js';
import {box,cylinder,person,sign} from './models.js';
import {WATER_DOCK,WATER_VICTIM,WATER_HANDOVER} from './water-rescue.js';
export function rescueBoat(parent,crew=false){const g=new T.Group();parent.add(g);box(g,1.7,.16,3.8,'#444b4b',0,.18,0);for(const x of[-.92,.92]){const tube=cylinder(g,.3,.3,3.7,'#d34432',x,.4,0,10);tube.rotation.x=Math.PI/2;}const bow=cylinder(g,.3,.3,1.85,'#d34432',0,.4,1.75,10);bow.rotation.z=Math.PI/2;const motor=new T.Group();motor.name='Moteur hors-bord';g.add(motor);motor.position.set(0,.5,-1.95);box(motor,.47,.48,.38,'#29353a',0,.18,0);box(motor,.13,.58,.14,'#62747a',0,-.35,-.03);const propeller=new T.Group();motor.add(propeller);propeller.position.set(0,-.58,-.14);for(const a of[0,Math.PI*2/3,Math.PI*4/3]){const blade=box(propeller,.06,.3,.025,'#9caeac',0,0,0);blade.rotation.z=a;}g.userData.motor=motor;g.userData.propeller=propeller;box(g,1.5,.15,.38,'#586366',0,.45,-.7);cylinder(g,.035,.035,1.3,'#627578',.62,1.1,-1.4,8);cylinder(g,.23,.23,.07,'#28343a',.62,1.75,-1.4,12);const beacon=cylinder(g,.21,.22,.24,new T.MeshStandardMaterial({color:'#378cce',emissive:'#168aff',emissiveIntensity:0}),.62,1.9,-1.4,16);g.userData.beacons=[beacon];installRotaryBeacons(g);g.userData.crew=[];if(crew)for(const x of[-.48,.48]){const p=diverResponder(g,x,-.55);g.userData.crew.push(p);p.scale.setScalar(.8);}g.userData.wake=createBoatWake(g);return g;}
export function installDiveKit(e){const trailer=new T.Group();trailer.name='Remorque porte-bateau';const hitch=new T.Group();hitch.name='Attelage articulé';e.model.add(hitch);hitch.add(trailer);
 const rear=-(e.model.userData.length||5)/2;hitch.position.z=rear-.35;trailer.position.z=-3.5;e.model.userData.trailerHitch=hitch;
 box(trailer,1.85,.15,3.7,'#8b9699',0,.65,0);
 for(const x of [-.7,.7]){const arm=box(trailer,.12,.12,2,'#8b9699',x/2,.62,2.5);arm.rotation.y=-x*.35;}
 box(trailer,.18,.15,.7,'#434d50',0,.62,3.5);
 trailer.userData.wheels=[];
 for(const x of [-1.08,1.08]){const tyre=cylinder(trailer,.43,.43,.28,'#252b2d',x,.43,-.2,16);tyre.rotation.z=Math.PI/2;trailer.userData.wheels.push(tyre);const hub=cylinder(trailer,.23,.23,.3,'#a7ada9',x,.43,-.2,12);hub.rotation.z=Math.PI/2;box(trailer,.4,.12,1.1,'#8b9699',x,.94,-.2);box(trailer,.22,.18,.1,'#c53525',x,.7,-1.95);}
 installRollingWheels(trailer);e.model.userData.wheels.push(...trailer.userData.wheels);
 const boat=rescueBoat(trailer);boat.position.set(0,.8,0);e.model.userData.carriedBoat=boat;e.model.userData.boatTrailer=trailer;e.model.userData.rearOverhang=5.8;for(const side of[-1,1]){const label=sign(e.model,'PLONGEURS',2.3,.35,side*1.09,1.85,-.6,'#bd292b','#ffffff');label.rotation.y=side*Math.PI/2;}}
export function updateWaterVisual(c,boat,victim,engine,seconds=0,camera={x:0,z:0}){const r=c.nautical;const active=!!r.unitId&&!r.done;boat.visible=active&&r.phase>0;updateRotaryBeacons(boat,boat.visible,seconds,camera);if(engine)engine.model.userData.carriedBoat.visible=!active;const t=r.progress,a=r.dock||WATER_DOCK,b=r.victim||WATER_VICTIM;let pos=a;if(r.phase===1)pos=a.map((v,i)=>v+(b[i]-v)*t);else if(r.phase===2)pos=b;else if(r.phase===3)pos=b.map((v,i)=>v+(a[i]-v)*t);boat.position.set(pos[0],waterHeight(pos[0],pos[1],seconds)-.15,pos[1]);boat.rotation.y=Math.atan2((r.phase>=3?a[0]-b[0]:b[0]-a[0]),(r.phase>=3?a[1]-b[1]:b[1]-a[1]));const moving=active&&(r.phase===1||r.phase===3),motion=seconds;boat.rotation.x=Math.sin(motion*2.3)*.012+(moving?-.025:0);boat.rotation.z=Math.sin(motion*1.7)*.022;const motor=boat.userData.motor;motor.rotation.y=moving?Math.sin(motion*.7)*.08:0;boat.userData.propeller.rotation.z=motion*(moving?32:3);updateBoatWake(boat,moving,boat.visible,motion);if(victim){victim.visible=!c.patients[0].evacuated;const carried=r.phase>=3&&!r.done,p=r.done?(r.handover||WATER_HANDOVER):carried?pos:b;victim.position.set(p[0],r.done?.6:carried?.9:.15,p[1]);}}
